                coords=[(rr,c) for rr in range(k+1,h) for c in range(w)]
                ref=lambda rr,c:g[k-1][c]
                near=lambda rr,c,v:g.__setitem__(k+1,g[k+1][:c]+[v]+g[k+1][c+1:])
                for rr,c in coords:
                    v=g[rr][c]
                    if v not in (bg,sep):
                        g[rr][c]=bg
                        if ref(rr,c)==v:g[k+1][c]=v
                        else:g[h-1][c]=v
            else:
                for rr in range(k):
                    for c in range(w):
                        v=g[rr][c]
                        if v not in (bg,sep):
                            g[rr][c]=bg
                            if g[k+1][c]==v:g[k-1][c]=v
                            else:g[0][c]=v
            return g
    for c in range(w):
        col=[g[r][c] for r in range(h)]
        if len(set(col))==1 and col[0]!=bg:
            k,sep=c,col[0]
            if w-k-1>k:
                for r in range(h):
